/**
 * Security Headers Generator (T5.8 Round 1)
 *
 * Generates Cloudflare Pages _headers file with security headers
 */

const SECURITY_HEADERS = `# Security Headers for IndexAI
# Generated by security-headers.js

# Content Security Policy - prevents XSS attacks
Content-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self' https:; connect-src 'self' https:; frame-ancestors 'none'; base-uri 'self'; form-action 'self'

# X-Content-Type-Options - prevents MIME type sniffing
X-Content-Type-Options: nosniff

# X-Frame-Options - prevents clickjacking attacks
X-Frame-Options: DENY

# X-XSS-Protection - enables browser XSS filtering
X-XSS-Protection: 1; mode=block

# Referrer-Policy - controls referrer information leakage
Referrer-Policy: strict-origin-when-cross-origin

# Permissions-Policy - restricts browser features
Permissions-Policy: accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=()

# Strict-Transport-Security - forces HTTPS (1 year)
Strict-Transport-Security: max-age=31536000; includeSubDomains; preload

# Cache-Control for static assets (1 year cache)
Cache-Control: public, max-age=31536000, immutable

# Remove server identification
Server:

# Prevent search engine indexing (optional, uncomment if needed)
# X-Robots-Tag: noindex, nofollow
`;

// Write to _headers file
fs.writeFileSync('_headers', SECURITY_HEADERS);
console.log('✓ Security headers written to _headers');

// Also write _headers for Cloudflare Pages deployment
fs.writeFileSync('./public/_headers', SECURITY_HEADERS);
console.log('✓ Security headers written to ./public/_headers');
